css:
.d-safe-markdown-subset{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-safe-markdown-subset *,.d-safe-markdown-subset *::before,.d-safe-markdown-subset *::after{box-sizing:border-box}
.d-safe-markdown-subset [hidden]{display:none!important}
.d-safe-markdown-subset .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-safe-markdown-subset .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-safe-markdown-subset label{display:block;margin:8px 0}
.d-safe-markdown-subset input,.d-safe-markdown-subset select,.d-safe-markdown-subset textarea,.d-safe-markdown-subset button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-safe-markdown-subset input:not([type=checkbox]):not([type=radio]),.d-safe-markdown-subset select,.d-safe-markdown-subset textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-safe-markdown-subset button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-safe-markdown-subset button:disabled{opacity:.5;cursor:default}
.d-safe-markdown-subset :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-safe-markdown-subset [aria-invalid=true]{border-color:var(--warn)!important}
.d-safe-markdown-subset .d-scroll{max-width:100%;overflow:auto}
.d-safe-markdown-subset table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-safe-markdown-subset th,.d-safe-markdown-subset td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-safe-markdown-subset caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-safe-markdown-subset progress{width:100%;accent-color:var(--ink)}
.d-safe-markdown-subset pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-safe-markdown-subset h3,.d-safe-markdown-subset p{margin:8px 0}
.d-safe-markdown-subset [aria-pressed=true],.d-safe-markdown-subset [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-safe-markdown-subset .d-grow{flex:1;min-width:100px}
.d-safe-markdown-subset summary{cursor:pointer;padding:6px 0}
.d-safe-markdown-subset ul,.d-safe-markdown-subset ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const draw=()=>{const fragment=document.createDocumentFragment();let list=null;for(const line of q('[data-input]').value.split(/\r?\n/)){if(line.startsWith('- ')){if(!list){list=document.createElement('ul');fragment.append(list);}const li=document.createElement('li');li.textContent=line.slice(2);list.append(li);}else{list=null;if(!line.trim())continue;const el=document.createElement(line.startsWith('# ')?'h3':'p');el.textContent=line.startsWith('# ')?line.slice(2):line;fragment.append(el);}}q('[data-result]').replaceChildren(fragment);say('已更新纯文本预览，仅支持一级标题和列表');};q('[data-preview]').onclick=draw;draw();})(root, q, qa, say);
}
